SELECT p.master_category AS master_category, p.sub_category AS sub_category, COUNT(DISTINCT p.product_id) AS product_count, COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END) AS distinct_base_colours, CASE WHEN COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END) = 0 THEN NULL ELSE ROUND(COUNT(DISTINCT p.product_id) * 1.0 / COUNT(DISTINCT CASE WHEN p.base_colour IS NOT NULL AND TRIM(p.base_colour) <> '' THEN p.base_colour END), 1) END AS products_per_colour FROM fashion.catalog.products p WHERE p.master_category IS NOT NULL AND TRIM(p.master_category) <> '' AND p.sub_category IS NOT NULL AND TRIM(p.sub_category) <> '' AND p.product_id IS NOT NULL GROUP BY p.master_category, p.sub_category HAVING COUNT(DISTINCT p.product_id) >= 100 ORDER BY products_per_colour DESC, product_count DESC, p.master_category ASC, p.sub_category ASC
